CARDS=[]
for line in RAW.strip().splitlines():
    cid,title,obs,slots,sources,owners,edges,en,ko,near,limit=line.split('|')
    owner_map=dict(x.split('=',1) for x in owners.split(';'))
    relations=[]
    for edge in edges.split(';'):
        a,p,b=edge.split('>'); relations.append({'from':a,'predicate':p,'to':b})
    CARDS.append(dict(card_id=cid,title_ko=title,observability=obs,proposed_slots=slots.split(','),
      source_ids=[f'S{int(x):02}' for x in sources.split(',')],owners=owner_map,directed_relations=relations,
      proposal_en=en,proposal_ko=ko,nearest_confusion_ko=near,claim_limit_ko=limit))

EXTRA_SOURCES={'B05':['S42'],'B07':['S45'],'B08':['S45'],'B09':['S45'],'E05':['S45'],'G02':['S44'],'K01':['S43']}
for card in CARDS:
    card['source_ids'] += EXTRA_SOURCES.get(card['card_id'],[])
    if card['card_id']=='K01':
        card['claim_limit_ko']='레이피어·방어 단검 병용의 역사 맥락을 S43으로 확인했다. 특정 물건의 도판·정확한 형식과 지역은 추가 검토한다. 소유자를 암살자로 단정하지 않는다.'
    if card['card_id']=='B04':
        card['directed_relations'] += [{'from':'pivot','predicate':'joins','to':'link1'},{'from':'pivot','predicate':'joins','to':'link2'}]
    if card['card_id']=='A12':
        card['owners']['socket']='accessible winding square'
        card['directed_relations'].append({'from':'socket','predicate':'beside','to':'indicator'})
    if card['card_id']=='G01':
        card['directed_relations'].append({'from':'sleeve','predicate':'part_of','to':'doublet'})
    if card['card_id']=='F02':
        card['directed_relations'][1]['predicate']='reveals'
    if card['card_id']=='M03':
        card['owners']['receiver']='one of the receiving vessels'
        card['directed_relations'][1]={'from':'water','predicate':'inside','to':'receiver'}
        card['directed_relations'].append({'from':'receiver','predicate':'member_of','to':'vessels'})
        card['proposal_en']=card['proposal_en'].replace('inside one vessel','inside one receiving vessel')
        card['proposal_ko']=card['proposal_ko'].replace('한 용기 안에','수수 용기 하나 안에')
